-- PT122-S4-Q11. Batch 03.
BEGIN;
DO $guard$ BEGIN IF NOT EXISTS (SELECT 1 FROM lr_questions q WHERE q.qid=$batch03$PT122-S4-Q11$batch03$ AND q.stimulus=$batch03$Consumer activist: When antilock brakes were first introduced, it was claimed that they would significantly reduce the incidence of multiple-car collisions, thereby saving lives. Indeed, antilock brakes have reduced the incidence of multiple-car collisions. I maintain, however, that to save lives, automobile manufacturers ought to stop equipping cars with them.$batch03$ AND q.prompt=$batch03$Which one of the following, if true, most helps to resolve the apparent conflict in the consumer activist's statements?$batch03$ AND q.correct_choice=$batch03$A$batch03$) THEN RAISE EXCEPTION 'Question changed: PT122-S4-Q11'; END IF; END $guard$;
DO $guard$ BEGIN IF (SELECT COUNT(*) FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id WHERE q.qid=$batch03$PT122-S4-Q11$batch03$ AND e.style IN ('single','standard')) <> 0 THEN RAISE EXCEPTION 'Explanation row changed: PT122-S4-Q11'; END IF; END $guard$;
INSERT INTO lr_explanations (question_id, style) SELECT q.id, 'single' FROM lr_questions q WHERE q.qid=$batch03$PT122-S4-Q11$batch03$ AND NOT EXISTS (SELECT 1 FROM lr_explanations e WHERE e.question_id=q.id AND e.style IN ('single','standard')) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_steps (explanation_id, position, label, body) SELECT e.id, v.position, v.label, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES (0, $batch03$Given that$batch03$, $batch03$Antilock brakes reduced multiple-car collisions, as promised.$batch03$), (1, $batch03$How can it be that$batch03$, $batch03$The activist says manufacturers should stop installing them to save lives?$batch03$), (2, $batch03$Evaluate$batch03$, $batch03$Fewer collisions does not have to mean fewer deaths. If the brakes change behavior in a way that makes crashes deadlier, they could cost more lives than they save.$batch03$), (3, $batch03$Goal$batch03$, $batch03$Find a way antilock brakes lead to more deaths despite fewer collisions.$batch03$)) v(position,label,body) WHERE q.qid=$batch03$PT122-S4-Q11$batch03$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_steps s WHERE s.explanation_id=e.id) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_choice_notes (explanation_id, letter, body) SELECT e.id, v.letter, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES ($batch03$A$batch03$, $batch03$People feel safer with antilock brakes and skip their seat belts. Each crash becomes more deadly, so total deaths can rise even as collisions fall.$batch03$), ($batch03$B$batch03$, $batch03$Traditional brakes stopping as quickly "under some circumstances" does not show antilock brakes cost lives.$batch03$), ($batch03$C$batch03$, $batch03$Antilock brakes being easier for new drivers is another safety benefit, which deepens the conflict.$batch03$), ($batch03$D$batch03$, $batch03$Cost has nothing to do with saving lives.$batch03$), ($batch03$E$batch03$, $batch03$Equal effectiveness against different kinds of accidents does not show the brakes increase deaths.$batch03$)) v(letter,body) WHERE q.qid=$batch03$PT122-S4-Q11$batch03$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_choice_notes n WHERE n.explanation_id=e.id AND n.letter=v.letter) ON CONFLICT DO NOTHING;
COMMIT;
